@* Vertical sidebar navigation for settings sections *@

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted text-uppercase fw-semibold small">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var tab in Tabs)
        {
            <li class="nav-item">
                <button class="nav-link w-100 text-start @(tab.Key == ActiveTab ? "active" : "")"
                        @onclick="() => OnTabSelected.InvokeAsync(tab.Key)">
                    <span class="me-2">@tab.Icon</span> @tab.Label
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveTab { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnTabSelected { get; set; }

    private record TabInfo(string Key, string Label, string Icon);

    private static readonly TabInfo[] Tabs =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

.settings-sidebar {
    min-width: 220px;
    border-right: 1px solid var(--bs-border-color);
    padding-top: 1rem;
    background: var(--bs-body-bg);
}

.settings-sidebar .nav-link {
    color: var(--bs-body-color);
    border-radius: 0;
    padding: 0.6rem 1rem;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.settings-sidebar .nav-link:hover {
    background: var(--bs-tertiary-bg);
}

.settings-sidebar .nav-link.active {
    background: var(--bs-primary-bg-subtle);
    color: var(--bs-primary);
    border-left-color: var(--bs-primary);
    font-weight: 600;
}

@using sv_6389c1a64804470a8a40b247fee93510.Services

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Profile Settings</h4>

        @if (_profile is null)
        {
            <p class="text-muted">Loading...</p>
            return;
        }

        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="_editName" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="_editEmail" />
                </div>
                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_editBio"></textarea>
                </div>
            </div>
            <div class="col-md-4 text-center">
                <label class="form-label fw-semibold d-block">Avatar Preview</label>
                <div class="avatar-preview mb-2">
                    <img src="@_profile.AvatarUrl" alt="Avatar" class="rounded-circle border"
                         width="120" height="120" />
                </div>
                <small class="text-muted text-break">@_profile.AvatarUrl</small>
            </div>
        </div>

        <div class="d-flex gap-2 mt-3">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@_saving">
                Discard Changes
            </button>
        </div>

        @if (_message is not null)
        {
            <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") mt-3 mb-0 py-2" role="alert">
                @_message
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private UserProfile? _profile;
    private string _editName = "";
    private string _editEmail = "";
    private string _editBio = "";
    private bool _saving;
    private string? _message;
    private bool _messageIsError;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        PopulateForm();
    }

    private void PopulateForm()
    {
        if (_profile is null) return;
        _editName = _profile.DisplayName;
        _editEmail = _profile.Email;
        _editBio = _profile.Bio;
    }

    private async Task SaveAsync()
    {
        if (_profile is null) return;
        _saving = true;
        _message = null;
        try
        {
            var updated = _profile with
            {
                DisplayName = _editName,
                Email = _editEmail,
                Bio = _editBio
            };
            await SettingsService.SaveProfileAsync(updated);
            _profile = updated;
            _message = "Profile saved successfully!";
            _messageIsError = false;
        }
        catch (Exception ex)
        {
            _message = $"Error saving profile: {ex.Message}";
            _messageIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        PopulateForm();
        _message = null;
    }
}

@using sv_6389c1a64804470a8a40b247fee93510.Services

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Notification Preferences</h4>

        @if (_prefs is null)
        {
            <p class="text-muted">Loading...</p>
            return;
        }

        <div class="mb-4">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif"
                       checked="@_emailNotif" @onchange="e => _emailNotif = (bool)e.Value!" />
                <label class="form-check-label" for="emailNotif">
                    Email Notifications
                </label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif"
                       checked="@_pushNotif" @onchange="e => _pushNotif = (bool)e.Value!" />
                <label class="form-check-label" for="pushNotif">
                    Push Notifications
                </label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest"
                       checked="@_weeklyDigest" @onchange="e => _weeklyDigest = (bool)e.Value!" />
                <label class="form-check-label" for="weeklyDigest">
                    Weekly Digest
                </label>
            </div>
        </div>

        <h6 class="fw-semibold">Muted Channels</h6>
        <p class="text-muted small">Uncheck channels you want to receive notifications from.</p>
        <div class="row mb-4">
            @foreach (var channel in _channels)
            {
                <div class="col-sm-6 mb-2">
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="ch-@channel.Name"
                               checked="@channel.IsMuted"
                               @onchange="e => channel.IsMuted = (bool)e.Value!" />
                        <label class="form-check-label" for="ch-@channel.Name">
                            @channel.Name
                        </label>
                    </div>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Preferences")
        </button>

        @if (_message is not null)
        {
            <div class="alert alert-success mt-3 mb-0 py-2" role="alert">@_message</div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotif, _pushNotif, _weeklyDigest;
    private List<ChannelEntry> _channels = [];
    private bool _saving;
    private string? _message;

    private class ChannelEntry { public string Name { get; set; } = ""; public bool IsMuted { get; set; } }

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotif = _prefs.EmailNotifications;
        _pushNotif = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = _prefs.MutedChannels
            .Select(c => new ChannelEntry { Name = c, IsMuted = true })
            .ToList();
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        var mutedList = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(_emailNotif, _pushNotif, _weeklyDigest, mutedList);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _message = "Preferences saved!";
        _saving = false;
    }
}

@if (_visible)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal fade show d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_device</strong>?</p>
                    <p class="text-muted small mb-0">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter, EditorRequired] public EventCallback<string> OnConfirm { get; set; }

    private bool _visible;
    private string _sessionId = "";
    private string _device = "";

    public void Show(string sessionId, string device)
    {
        _sessionId = sessionId;
        _device = device;
        _visible = true;
        StateHasChanged();
    }

    private async Task Confirm()
    {
        _visible = false;
        await OnConfirm.InvokeAsync(_sessionId);
    }

    private void Cancel()
    {
        _visible = false;
    }
}

@using sv_6389c1a64804470a8a40b247fee93510.Services

<div class="table-responsive">
    <table class="table table-hover align-middle mb-0">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>
                        @session.Device
                        @if (session.Id == CurrentSessionId)
                        {
                            <span class="badge bg-success ms-1">Current</span>
                        }
                    </td>
                    <td>@session.Location</td>
                    <td>@FormatLastActive(session.LastActive)</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn btn-outline-danger btn-sm"
                                    @onclick="() => OnRevokeRequest.InvokeAsync((session.Id, session.Device))">
                                Revoke
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter, EditorRequired] public EventCallback<(string Id, string Device)> OnRevokeRequest { get; set; }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 5) return "Just now";
        if (diff.TotalHours < 1) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalDays < 1) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_6389c1a64804470a8a40b247fee93510.Services

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Security</h4>

        @if (_security is null)
        {
            <p class="text-muted">Loading...</p>
            return;
        }

        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <span class="badge @(_twoFactor ? "bg-success" : "bg-secondary")">
                            @(_twoFactor ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactorToggle"
                               checked="@_twoFactor"
                               @onchange="e => _twoFactor = (bool)e.Value!" />
                    </div>
                </div>
                @if (_security.LastPasswordChange.HasValue)
                {
                    <small class="text-muted d-block mt-2">
                        Last password change: @_security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </small>
                }
            </div>
        </div>

        <div class="card">
            <div class="card-header fw-semibold">Active Sessions</div>
            <div class="card-body p-0">
                <ActiveSessionsTable Sessions="_security.Sessions.ToList()"
                                     OnRevokeRequest="RequestRevoke" />
            </div>
        </div>

        <RevokeSessionDialog @ref="_revokeDialog" OnConfirm="RevokeSessionAsync" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _security;
    private bool _twoFactor;
    private RevokeSessionDialog _revokeDialog = default!;

    protected override async Task OnInitializedAsync()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactor = _security.TwoFactorEnabled;
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private void RequestRevoke((string Id, string Device) args)
    {
        _revokeDialog.Show(args.Id, args.Device);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }
}

