</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotif, _pushNotif, _weeklyDigest;
    private List<ChannelEntry> _channels = [];
    private bool _saving;
    private string? _message;

    private class ChannelEntry { public string Name { get; set; } = ""; public bool IsMuted { get; set; } }

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotif = _prefs.EmailNotifications;
        _pushNotif = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = _prefs.MutedChannels
            .Select(c => new ChannelEntry { Name = c, IsMuted = true })
            .ToList();
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        var mutedList = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(_emailNotif, _pushNotif, _weeklyDigest, mutedList);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _message = "Preferences saved!";
        _saving = false;
    }
}

