<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Notification Preferences</h4>

        @if (_prefs is null)
        {
            <p class="text-muted">Loading...</p>
            return;
        }

        <div class="mb-4">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif"
                       checked="@_emailNotif" @onchange="e => _emailNotif = (bool)e.Value!" />
                <label class="form-check-label" for="emailNotif">
                    Email Notifications
                </label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif"
                       checked="@_pushNotif" @onchange="e => _pushNotif = (bool)e.Value!" />
                <label class="form-check-label" for="pushNotif">
                    Push Notifications
                </label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest"
                       checked="@_weeklyDigest" @onchange="e => _weeklyDigest = (bool)e.Value!" />
                <label class="form-check-label" for="weeklyDigest">
                    Weekly Digest
                </label>
            </div>
        </div>

        <h6 class="fw-semibold">Muted Channels</h6>
        <p class="text-muted small">Uncheck channels you want to receive notifications from.</p>
        <div class="row mb-4">
            @foreach (var channel in _channels)
            {
                <div class="col-sm-6 mb-2">
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="ch-@channel.Name"
                               checked="@channel.IsMuted"
                               @onchange="e => channel.IsMuted = (bool)e.Value!" />
                        <label class="form-check-label" for="ch-@channel.Name">
                            @channel.Name
                        </label>
                    </div>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save Preferences")
        </button>

        @if (_message is not null)
        {
            <div class="alert alert-success mt-3 mb-0 py-2" role="alert">@_message</div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotif, _pushNotif, _weeklyDigest;
    private List<ChannelEntry> _channels = [];
    private bool _saving;
    private string? _message;

    private class ChannelEntry { public string Name { get; set; } = ""; public bool IsMuted { get; set; } }

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotif = _prefs.EmailNotifications;
        _pushNotif = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = _prefs.MutedChannels
            .Select(c => new ChannelEntry { Name = c, IsMuted = true })
            .ToList();
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        var mutedList = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var updated = new NotificationPrefs(_emailNotif, _pushNotif, _weeklyDigest, mutedList);
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _message = "Preferences saved!";
        _saving = false;
    }
}
