    <h6 style="@HeadingStyle()">Preview</h6>
    <p style="@TextStyle()">
        This is how your content will look with the current settings.
    </p>
    <div class="d-flex gap-2">
        <button class="btn btn-sm btn-primary">Primary Action</button>
        <button class="btn btn-sm btn-outline-secondary">Secondary</button>
    </div>
