        <span class="badge bg-info">Status badge</span>
        <span class="text-muted" style="@TextStyle()"> — sample text</span>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public bool CompactMode { get; set; }

    private string PreviewStyle()
    {
        var bg = Theme switch
        {
            "Dark" => "background:#1e1e2e; color:#cdd6f4;",
            "System" => "background:#f0f0f0; color:#333;",
            _ => "background:#ffffff; color:#212529;"
        };
        var padding = CompactMode ? "padding:0.5rem;" : "padding:1rem;";
        return $"{bg} {padding}";
    }

    private string HeadingStyle() => $"font-size:{SizeValue(1.1)}rem;";
    private string TextStyle() => $"font-size:{SizeValue(0.9)}rem;";

    private double SizeValue(double baseSize) => FontSize switch
    {
        "Small" => baseSize * 0.85,
        "Large" => baseSize * 1.2,
        _ => baseSize
    };
}
