@using sv_6389c1a64804470a8a40b247fee93510.Services

<div class="table-responsive">
    <table class="table table-hover align-middle mb-0">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>
                        @session.Device
                        @if (session.Id == CurrentSessionId)
                        {
                            <span class="badge bg-success ms-1">Current</span>
                        }
                    </td>
                    <td>@session.Location</td>
                    <td>@FormatLastActive(session.LastActive)</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            <button class="btn btn-outline-danger btn-sm"
                                    @onclick="() => OnRevokeRequest.InvokeAsync((session.Id, session.Device))">
                                Revoke
                            </button>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter, EditorRequired] public EventCallback<(string Id, string Device)> OnRevokeRequest { get; set; }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 5) return "Just now";
        if (diff.TotalHours < 1) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalDays < 1) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@using sv_6389c1a64804470a8a40b247fee93510.Services

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Security</h4>

        @if (_security is null)
        {
            <p class="text-muted">Loading...</p>
            return;
        }

        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <span class="badge @(_twoFactor ? "bg-success" : "bg-secondary")">
                            @(_twoFactor ? "Enabled" : "Disabled")
                        </span>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactorToggle"
                               checked="@_twoFactor"
                               @onchange="e => _twoFactor = (bool)e.Value!" />
                    </div>
                </div>
                @if (_security.LastPasswordChange.HasValue)
                {
                    <small class="text-muted d-block mt-2">
                        Last password change: @_security.LastPasswordChange.Value.ToString("MMM dd, yyyy")
                    </small>
                }
            </div>
        </div>

        <div class="card">
            <div class="card-header fw-semibold">Active Sessions</div>
            <div class="card-body p-0">
                <ActiveSessionsTable Sessions="_security.Sessions.ToList()"
                                     OnRevokeRequest="RequestRevoke" />
            </div>
        </div>

        <RevokeSessionDialog @ref="_revokeDialog" OnConfirm="RevokeSessionAsync" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _security;
    private bool _twoFactor;
    private RevokeSessionDialog _revokeDialog = default!;

    protected override async Task OnInitializedAsync()
    {
        _security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactor = _security.TwoFactorEnabled;
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private void RequestRevoke((string Id, string Device) args)
    {
        _revokeDialog.Show(args.Id, args.Device);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }
}

