@page "/settings"
@using sv_6389c1a64804470a8a40b247fee93510.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveTab="@_activeTab" OnTabSelected="tab => _activeTab = tab" />

    <div class="settings-content p-4">
        @switch (_activeTab)
        {
            case "profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </div>
</div>

